R=/scratch/jjyeung/orch_n30
date -u +%TZ
for p in $(pgrep -f "agent -p" ); do echo "$p $(readlink /proc/$p/cwd) $(ps -o etime= -p $p)"; done
ps -o pid,etime,cmd -p 562823 2>/dev/null | cut -c1-120
kill -TERM 562823 2>/dev/null && echo "TERM sent 562823"; sleep 5; ps -o pid= -p 562823 && kill -KILL 562823 && echo KILLED
for t in sb_phrev sb_carev sb_cfrev; do mkdir -p $R/$t/prompts $R/$t/out; done
echo  | base64 -d > $R/sb_phrev/prompts/sb_phrev.md; echo  | base64 -d > $R/sb_carev/prompts/sb_carev.md; echo  | base64 -d > $R/sb_cfrev/prompts/sb_cfrev.md
{ cat $R/sb_queue/queue.txt; echo sb_phrev; echo sb_carev; echo sb_cfrev; } > $R/sb_queue/q.tmp; cat $R/sb_queue/q.tmp > $R/sb_queue/queue.txt; echo Q: $(cat $R/sb_queue/queue.txt | tr "\n" " ")
ls $R/sb_mask_phrase/out | tr "\n" " "; echo
tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "
